    [7731] = { level=254, name="Enchant Palladium", scroll_id=0, expac=3, mana=330, cast_ms=6000, icon=2521, effectid1=32, desc="Self Summon", lore="This ability allows you to enchant a bar of palladium with magical energy.  Consumes a bar of palladium when cast." },
    [7732] = { level=254, name="Enchant Dwerium", scroll_id=0, expac=3, mana=390, cast_ms=6000, icon=2521, effectid1=32, desc="Self Summon", lore="This ability allows you to enchant a bar of dwerium using some of your mana." },
    [7733] = { level=254, name="Mass Enchant Palladium", scroll_id=0, expac=3, mana=1980, cast_ms=10000, icon=2521, effectid1=32, desc="Self Summon", lore="This ability allows you to enchant ten bars of palladium with magical energy. Consumes ten bars of palladium when cast." },
    [7734] = { level=254, name="Mass Enchant Dwerium", scroll_id=0, expac=3, mana=3120, cast_ms=10000, icon=2521, effectid1=32, desc="Self Summon", lore="This ability allows you to enchant ten bars of dwerium using some of your mana." },
    [7865] = { level=254, name="Enchant Palladium Trio", scroll_id=0, expac=3, mana=660, cast_ms=8000, icon=2521, effectid1=32, desc="Self Summon", lore="This ability allows you to enchant three bars of palladium with magical energy. Consumes three bars of palladium when cast." },
    [7985] = { level=19, name="Greater Mass Enchant Electrum", scroll_id=37591, expac=3, mana=900, cast_ms=20000, icon=2521, effectid1=32, desc="Self Summon", lore="Enchants twenty bars of electrum with magical energy.  Consumes twenty bars of electrum when cast." },
    [7986] = { level=28, name="Greater Mass Enchant Gold", scroll_id=37592, expac=3, mana=1800, cast_ms=20000, icon=2521, effectid1=32, desc="Self Summon", lore="Enchants twenty bars of gold with magical energy. Consumes twenty bars of gold when cast." },
    [7987] = { level=38, name="Greater Mass Enchant Platinum", scroll_id=37593, expac=3, mana=2700, cast_ms=20000, icon=2521, effectid1=32, desc="Self Summon", lore="Enchants twenty bars of platinum with magical energy. Consumes twenty bars of platinum when cast." },
    [7988] = { level=11, name="Greater Mass Enchant Silver", scroll_id=37594, expac=3, mana=720, cast_ms=20000, icon=2521, effectid1=32, desc="Self Summon", lore="Enchants twenty bars of silver with magical energy.  Consumes twenty bars of silver when cast." },
    [7989] = { level=44, name="Greater Mass Enchant Velium", scroll_id=37595, expac=3, mana=2400, cast_ms=20000, icon=2521, effectid1=32, desc="Self Summon", lore="Enchants twenty bars of velium with magical energy. Consumes twenty bars of velium when cast." },
    [7990] = { level=254, name="Greater Mass Enchant Palladium", scroll_id=0, expac=3, mana=3960, cast_ms=20000, icon=2521, effectid1=32, desc="Self Summon", lore="This ability allows you to enchant twenty bars of palladium with magical energy. Consumes twenty bars of palladium when cast." },
    [7994] = { level=70, name="Dread Pyre", scroll_id=41265, expac=3, mana=1093, cast_ms=3000, icon=2500, effectid1=0, desc="Poison DD", lore="Consumes your target in a burning pyre of blood, causing @1 damage every 6 seconds for up to %z." },
    [7995] = { level=68, name="Call for Blood", scroll_id=41266, expac=3, mana=568, cast_ms=6000, icon=2503, effectid1=0, desc="Banish", lore="Afflicts your target with a hungry toxin that will cause @1 damage.  The venom will attempt to absorb energy from the creatures that can sometimes be controlled to give a temporary increase to the power of your duration damage spells.  However, there is also a chance that the energy will backfire and cause the power of your damage over time spells to drop for a short time." },
    [7999] = { level=69, name="Corath Venom", scroll_id=41267, expac=3, mana=655, cast_ms=3000, icon=2500, effectid1=36, desc="Poison DD", lore="Fills your target's veins with corathus venom for up to %z.  Initially this venom will cause @2 damage but will decrease in potency the longer it afflicts the target." },
    [8004] = { level=68, name="Death's Regret", scroll_id=41272, expac=3, mana=340, cast_ms=5000, icon=2503, effectid1=0, desc="Undead Banish", lore="Strikes down an undead target with divine energy, causing @1 damage and potentially slowing their movement and doing additional damage for a short time." },
    [8006] = { level=69, name="Chromastrike", scroll_id=41273, expac=3, mana=375, cast_ms=6000, icon=2503, effectid1=0, desc="Fire DD", lore="Channels holy power into a cohesive bolt of energy, causing @1 damage.  The holy power attempts to breach the weakest of your target's magical defenses, and is therefore harder to resist." },
    [8007] = { level=70, name="Desperate Renewal", scroll_id=41274, expac=3, mana=1375, cast_ms=3000, icon=2510, effectid1=0, desc="Heal", lore="Channels holy power to heal your target for up to @1 hit points as well as attempting to remove poisons, diseases, and curses." },
    [8008] = { level=68, name="Skin of the Reptile", scroll_id=41275, expac=3, mana=512, cast_ms=3000, icon=2503, effectid1=10, desc="Banish", lore="Causes your target's skin to take on a reptilian appearance. When the target is struck by melee combat the skin will often attempt to heal its wounds." },
    [8010] = { level=69, name="Spore Spiral", scroll_id=41276, expac=3, mana=200, cast_ms=3000, icon=2513, effectid1=10, desc="Fire DD", lore="Fires a cluster of spores at your target that will fling them backwards and root them to the ground for a short time." },
    [8011] = { level=70, name="Dawnstrike", scroll_id=41277, expac=3, mana=482, cast_ms=7000, icon=2515, effectid1=0, desc="DmgShield", lore="Channels the power of the dawn to strike your target for @1 damage.  While channeling this power you will sometimes gain the blessing of the dawn, which will greatly increase your next direct damage spell.  However, there is also a small chance that the energy will backfire and cause your next several direct damage spells to do less damage." },
    [8015] = { level=68, name="Lingering Sloth", scroll_id=41278, expac=3, mana=500, cast_ms=3000, icon=2503, effectid1=10, desc="Banish", lore="Summons a protective spirit to guard your target for %z.  The spirit can intervene when a creature strikes your target, lowering the creature's attack speed." },
    [8017] = { level=70, name="Hungry Plague", scroll_id=41279, expac=3, mana=450, cast_ms=3000, icon=2501, effectid1=10, desc="Slow", lore="Afflicts your target with a hungry plague that will slow their attack rate for up to %z.  The plague will freqently attempt to infect nearby targets with the same malady." },
    [8018] = { level=69, name="Breath of Antraygus", scroll_id=41280, expac=3, mana=700, cast_ms=3000, icon=2513, effectid1=0, desc="Cone Fire DD", lore="Spews a deluge of acid in a cone in front of you, causing up to @1 damage to any creatures caught in the spray." },
    [8020] = { level=68, name="Hail of Arrows", scroll_id=41282, expac=3, mana=350, cast_ms=3000, icon=2513, effectid1=193, desc="Cone Fire DD", lore="Conjures a hail of ethereal arrows to fly out in front of you, causing damage to any creatures caught in the arc." },
    [8021] = { level=68, name="Bestial Empathy", scroll_id=41283, expac=3, mana=525, cast_ms=3000, icon=2512, effectid1=152, desc="DD", lore="Beckons to the creatures of the wild to attack your target for a short time." },
    [8022] = { level=68, name="Fickle Shadows", scroll_id=41284, expac=3, mana=280, cast_ms=500, icon=2503, effectid1=0, desc="Undead Banish", lore="Tears the unholy energy from an undead target, causing @1 damage.  The energy torn from the creature can sometimes be focused to greatly enhance the damage of your next lifetap spell.  However, sometimes the energy can backfire and greatly decrease the power of your lifetap spells for a short time." },
    [8025] = { level=69, name="Touch of Draygun", scroll_id=41285, expac=3, mana=380, cast_ms=3000, icon=2507, effectid1=0, desc="Weaken", lore="Rips the life from your target, inflicting @1 damage.  This life energy will increase your maximum hit points temporarily, though the maximum hit points gained will decay over time." },
    [8027] = { level=68, name="Last Rites", scroll_id=41286, expac=3, mana=300, cast_ms=500, icon=2503, effectid1=0, desc="Undead Banish", lore="Squelches the darkness in an undead creature, causing @1 damage and potentially slowing their movement speed and lowering their armor class for a short time." },
    [8029] = { level=69, name="Silent Piety", scroll_id=41287, expac=3, mana=300, cast_ms=6000, icon=2518, effectid1=10, desc="Self Stat Buff", lore="Cloaks you in a pious aura that will sometimes turn away detrimental spells for up to %z." },
    [8031] = { level=68, name="Creeping Dreams", scroll_id=41289, expac=3, mana=100, cast_ms=3000, icon=2503, effectid1=31, desc="Bard DD", lore="Fills your target's mind with creeping dreams, causing them to cease actions for up to %z.  The dreams take on a sentience of their own and will try to spread to nearby enemies periodically." },
    [8032] = { level=70, name="Mana Flare", scroll_id=41290, expac=3, mana=700, cast_ms=3000, icon=2518, effectid1=339, desc="Stat Buff", lore="Places an aura of mana upon your target.  The mana will entwine with the energy of a damaging spell, allowing your target to inflict additional damage via a mana flare strike.  Mana flare strikes generate little to no anger." },
    [8034] = { level=69, name="Colored Chaos", scroll_id=41291, expac=3, mana=425, cast_ms=6000, icon=2503, effectid1=0, desc="Fire DD", lore="Coalesces mana into a spectrum of destructive light, causing #1 damage to your target.  The light will attempt to breach the weakest of your target's defenses and is therefore much harder to resist." },
    [8035] = { level=68, name="Echoing Madness", scroll_id=41292, expac=3, mana=700, cast_ms=3000, icon=2503, effectid1=31, desc="Bard DD", lore="Seeds an echo of madness in your target, causing them to cease their actions for up to %z.  The madness will frequently echo in the ears of nearby creatures as well." },
    [8036] = { level=54, name="Illusion: Orc", scroll_id=77918, expac=3, mana=150, cast_ms=3000, icon=2521, effectid1=58, desc="Self Illusion", lore="Cloaks you in the guise of an orc. Roar." },
    [8037] = { level=70, name="Raging Servant", scroll_id=41293, expac=3, mana=1650, cast_ms=3000, icon=2512, effectid1=152, desc="DD", lore="Summons a raging elemental servant that will relentlessly attack your opponent for a short time." },
    [8038] = { level=68, name="Burning Aura", scroll_id=41294, expac=3, mana=300, cast_ms=3000, icon=2503, effectid1=323, desc="Banish", lore="Cloaks your target in an aura of flames.  The flames will frequently lash out at an attacking creatures causing moderate damage.." },
    [8040] = { level=69, name="Fickle Fire", scroll_id=41295, expac=3, mana=519, cast_ms=6350, icon=2515, effectid1=0, desc="DmgShield", lore="Strikes your target with a bolt of focused elemental fire, causing @1 damage.  The force of this fire can sometimes be harnessed to greatly increase the damage of your next direct damage spell.  However, the fire can sometimes backfire and cause your direct damage spells to do much less damage for a short time." },
    [8041] = { level=68, name="Clinging Frost", scroll_id=41296, expac=3, mana=350, cast_ms=4000, icon=2519, effectid1=0, desc="Cold DD", lore="Strikes your target with a clinging bolt of frost causing #1 damage.  The frost will slow your target's movements for a short time." },
    [8043] = { level=70, name="Ether Flame", scroll_id=41297, expac=3, mana=1550, cast_ms=8000, icon=2515, effectid1=0, desc="Fire AoE", lore="Summons the pure energy of ethereal fire to strike your target, causing @1 damage." },
    [8044] = { level=69, name="Mana Weave", scroll_id=41298, expac=3, mana=670, cast_ms=7000, icon=2515, effectid1=0, desc="DmgShield", lore="Weaves mana into a bolt of burning energy that will cause @1 damage to your target.  The energy of this weave can sometimes be harnessed to greatly increase the power of your next direct damage spell.  However, the weave can sometimes become unstable and make your direct damage spells cause less damage for a short time." },
