    [8468] = { level=70, name="Champion's Aura", scroll_id=43563, expac=3, mana=0, cast_ms=3000, icon=2512, effectid1=351, desc="Self Summon", lore="Increases your companions' natural armor and chance to trigger weapon effects, as long as they stay inside the area of the aura." },
    [8471] = { level=70, name="Poison Spikes Trap", scroll_id=43564, expac=3, mana=0, cast_ms=6000, icon=2512, effectid1=351, desc="Self Summon", lore="Constructs a trap of poison spikes at your feet which will trigger when enemies draw near and slow their movement rate." },
    [8474] = { level=70, name="Master's Aura", scroll_id=43565, expac=3, mana=0, cast_ms=3000, icon=2512, effectid1=351, desc="Self Summon", lore="Increases your companions' chance to dodge, parry, and riposte attacks, as long as they stay inside the area of the aura." },
    [8477] = { level=70, name="Bloodlust Aura", scroll_id=43566, expac=3, mana=0, cast_ms=3000, icon=2512, effectid1=351, desc="Self Summon", lore="Fills those around you with bloodlust, increasing the damage that their critical strikes will cause.  The effect only benefits those that stay within the area of your aura." },
    [8479] = { level=70, name="Ward of Tunare", scroll_id=77988, expac=3, mana=545, cast_ms=3000, icon=2503, effectid1=2, desc="Self Proc", lore="Bathes your body in a holy aura that will sometimes heal your wounds when struck in melee combat.  The ward will also increase your attack rating, your strength, and your armor class." },
    [8481] = { level=70, name="Blessed Aura", scroll_id=43567, expac=3, mana=400, cast_ms=3000, icon=2512, effectid1=351, desc="Self Summon", lore="Increases the potency of healing spells that land on your companions, as long as they stay inside the area of the aura." },
    [8483] = { level=70, name="Theft of Agony", scroll_id=77990, expac=3, mana=100, cast_ms=1500, icon=2513, effectid1=10, desc="Spell", lore="Incites intense pain and hatred in your target.  You in turn use that pain to increase your own armor class.  The effects of this increased armor will fade over time." },
    [8484] = { level=70, name="Decrepit Skin", scroll_id=43568, expac=3, mana=545, cast_ms=3000, icon=2512, effectid1=323, desc="Self Summon", lore="Gives your skin a sickly hue that will sometimes harden to absorb the impact of attacks made against you." },
    [8486] = { level=70, name="Arcane Aria", scroll_id=77992, expac=3, mana=0, cast_ms=3000, icon=2503, effectid1=339, desc="Group Proc", lore="Conjures the power of your voice into arcane orbs of power that will fuel the destructive power of group members who use direct damage spells." },
    [8488] = { level=70, name="Aura of the Muse", scroll_id=43569, expac=3, mana=0, cast_ms=3000, icon=2512, effectid1=351, desc="Self Summon", lore="Increases your companions' attack speed and spell damage, as long as they stay inside the area of the aura." },
    [8490] = { level=70, name="Scorched Earth", scroll_id=77994, expac=3, mana=365, cast_ms=500, icon=2515, effectid1=0, desc="DmgShield", lore="Calls down fire to consume your target, causing #1 damage." },
    [8491] = { level=70, name="Elddar's Grasp", scroll_id=43570, expac=3, mana=180, cast_ms=3000, icon=2513, effectid1=10, desc="Fire DD", lore="Entangles your target's feet in the vines of the Elddar, preventing them from moving up for up to %z.  This spell is very difficult to resist." },
    [8493] = { level=70, name="Elixir of Divinity", scroll_id=77996, expac=3, mana=1550, cast_ms=5000, icon=2510, effectid1=100, desc="Group Heal", lore="Fills your group with holy energy which will continually heal their wounds for a short period of time." },
    [8494] = { level=70, name="Puratus", scroll_id=43571, expac=3, mana=100, cast_ms=6000, icon=2510, effectid1=335, desc="Heal", lore="Cleanses your target of poisons and prevents the next poison-based spell from affecting them." },
    [8495] = { level=70, name="Aura of the Pious", scroll_id=77998, expac=3, mana=500, cast_ms=3000, icon=2512, effectid1=351, desc="Self Summon", lore="Allows your companions to absorb a portion of incoming melee damage, as long as they stay inside the area of the aura." },
    [8498] = { level=70, name="Moonshadow", scroll_id=43572, expac=3, mana=1100, cast_ms=4500, icon=2510, effectid1=0, desc="Group Heal", lore="Bathes your group in the light of the moon, healing their wounds." },
    [8499] = { level=70, name="Aura of Life", scroll_id=78001, expac=3, mana=400, cast_ms=3000, icon=2512, effectid1=351, desc="Self Summon", lore="Increases your companions' health regeneration and also removes their disease effects, as long as they stay inside the area of the aura." },
    [8501] = { level=70, name="Nectar of Pain", scroll_id=78002, expac=3, mana=660, cast_ms=3000, icon=2500, effectid1=36, desc="Poison DD", lore="Poisons the target, dealing more than #2 damage every six seconds for %z." },
    [8503] = { level=70, name="Ghost of Renewal", scroll_id=43573, expac=3, mana=1260, cast_ms=5000, icon=2510, effectid1=100, desc="Group Heal", lore="Increases hit points by up to #1 every six seconds for %z." },
    [8504] = { level=70, name="Idol of Malos", scroll_id=78004, expac=3, mana=200, cast_ms=3000, icon=2512, effectid1=351, desc="Self Summon", lore="Conjures an Idol of Malos at your location, which will lower resistances for any enemies that approach." },
    [8506] = { level=70, name="Ward of Bedazzlement", scroll_id=78005, expac=3, mana=500, cast_ms=6000, icon=2503, effectid1=323, desc="Self Proc", lore="Adds a chance for creatures that strike you to be mesmerized for a brief period." },
    [8508] = { level=70, name="Mind Shatter", scroll_id=43574, expac=3, mana=525, cast_ms=3000, icon=2503, effectid1=10, desc="Drowning", lore="Strangles your target's brain, causing them #4 damage every 6 seconds as well as draining their mana.  The mana drained will help restore your own." },
    [8509] = { level=70, name="Illusionist's Aura", scroll_id=78007, expac=3, mana=500, cast_ms=3000, icon=2512, effectid1=351, desc="Self Summon", lore="Increases your companions' mana regeneration, as long as they stay inside the area of the aura." },
    [8511] = { level=70, name="Ice Block", scroll_id=78008, expac=3, mana=180, cast_ms=1750, icon=2519, effectid1=10, desc="Spell", lore="Encases your target's feet in solid ice, causing #1 damage and preventing them from moving for a short time." },
    [8512] = { level=70, name="Chaos Flame", scroll_id=43575, expac=3, mana=275, cast_ms=3000, icon=2521, effectid1=0, desc="Stun", lore="Evokes a potent magical flame to strike your target, causing between #1 and @1 damage." },
    [8513] = { level=70, name="Fire Rune", scroll_id=78010, expac=3, mana=100, cast_ms=3000, icon=2512, effectid1=351, desc="Self Summon", lore="Scribes a fiery rune on the ground that will explode and damage any enemy that wanders too close." },
    [8515] = { level=70, name="Spear of Ro", scroll_id=78011, expac=3, mana=684, cast_ms=7000, icon=2515, effectid1=0, desc="DD", lore="Strikes your target with the spear of Ro, causing #1 damage." },
    [8517] = { level=70, name="Iceflame Guard", scroll_id=43576, expac=3, mana=200, cast_ms=3000, icon=2515, effectid1=10, desc="Pet DmgShield", lore="Cloaks your pet in an iceflame guard which will cause damage to any creature that strikes it in melee combat, as well as granting a chance to strike enemies with fire.  The combat effect will also cause your pet to be cloaked in a brief protective aura that will absorb one melee attack or spell." },
    [8518] = { level=70, name="Rathe's Strength", scroll_id=78013, expac=3, mana=400, cast_ms=6000, icon=2512, effectid1=351, desc="Pet Summon", lore="Augments your pet with the strength of the Rathe which will increase their melee damage by 10 percent.  The effect will also augment all nearby pets by the same amount." },
    [8520] = { level=70, name="Grave Pact", scroll_id=78014, expac=3, mana=5, cast_ms=3000, icon=2507, effectid1=374, desc="Self Proc", lore="Turns your body into that of the undead, increasing your mana regeneration, granting you ultravision, the ability to see invisible creatures and the form of a skeleton.  You will continually take damage while in this form." },
    [8522] = { level=70, name="Mind Flay", scroll_id=43577, expac=3, mana=700, cast_ms=6000, icon=2507, effectid1=10, desc="Lifetap DoT", lore="Steals the mental energy of your target to regenerate the mana of your group mates." },
    [8523] = { level=70, name="Death Rune", scroll_id=78016, expac=3, mana=100, cast_ms=6000, icon=2512, effectid1=351, desc="Self Summon", lore="Scribes a rune of death on the ground that will curse any creature that wanders too close to it.  The curse will cause continual damage to the creature for a short time." },
    [8771] = { level=254, name="Alter Plane: Theater of Blood", scroll_id=0, expac=3, mana=0, cast_ms=5000, icon=2522, effectid1=83, desc="Self Teleport", lore="Teleports you to the Theater of Blood." },
