    [8921] = { level=55, name="Myrmidon's Aura", scroll_id=78019, expac=3, mana=0, cast_ms=6000, icon=2512, effectid1=351, desc="Self Summon", lore="Increases your companions' natural armor and chance to trigger weapon effects, as long as they stay inside the area of the aura." },
    [8922] = { level=55, name="Poison Spurs Trap", scroll_id=78020, expac=3, mana=0, cast_ms=6000, icon=2512, effectid1=351, desc="Self Summon", lore="Constructs a trap of poison spikes at your feet which will trigger when enemies draw near and slow their movement rate." },
