    [8924] = { level=55, name="Aura of Rage", scroll_id=78022, expac=3, mana=0, cast_ms=6000, icon=2512, effectid1=351, desc="Self Summon", lore="Fills those around you with bloodlust, increasing the damage that their critical strikes will cause.  The effect only benefits those that stay within the area of your aura." },
    [8925] = { level=55, name="Holy Aura", scroll_id=78023, expac=3, mana=340, cast_ms=6000, icon=2512, effectid1=351, desc="Self Summon", lore="Increases the potency of healing spells that land on your companions, as long as they stay inside the area of the aura." },
