    [8928] = { level=55, name="Aura of the Zealot", scroll_id=78025, expac=3, mana=416, cast_ms=6000, icon=2512, effectid1=351, desc="Self Summon", lore="Allows your companions' to absorb a portion of incoming melee damage, as long as they stay inside the area of the aura." },
    [8929] = { level=55, name="Aura of the Grove", scroll_id=78026, expac=3, mana=40, cast_ms=6000, icon=2512, effectid1=351, desc="Self Summon", lore="Increases your companions' health regeneration and also removes their disease effects, as long as they stay inside the area of the aura." },
