    [11879] = { level=73, name="Aviak's Wondrous Warble", scroll_id=79420, expac=3, mana=0, cast_ms=3000, icon=2511, effectid1=78, desc="Group Mana", lore="Those that hear the wondrous warble move with a bird-like precision and fluidity that grants them increased armor class, resistance to detrimental spells, and reduced damage shield taken from offhand attacks." },
