    [11885] = { level=74, name="Rune of the Kedge", scroll_id=79423, expac=3, mana=1800, cast_ms=5000, icon=2511, effectid1=55, desc="Group AC Buff", lore="Covers your group in runes of the Kedge, which will absorb #1 incoming damage.  Enemies that strike those protected by these runes can lose anger for their target.  This spell generates little to no anger.  Consumes a pair of peridots when cast." },
