    [11897] = { level=75, name="Mind Phobiate", scroll_id=79429, expac=3, mana=594, cast_ms=3000, icon=2503, effectid1=10, desc="Drowning", lore="Strangles your target's brain, causing #4 damage every 6 seconds for %z.  The phobiate steals up to #2 mana from your target and uses it to restore your own." },
