    [11903] = { level=73, name="Mana Recursion", scroll_id=79432, expac=3, mana=840, cast_ms=3000, icon=2518, effectid1=339, desc="Stat Buff", lore="Places an aura of recursive mana upon your target.  The mana will entwine with the energy of a damaging spell, allowing your target to inflict additional damage via a mana recursion strike.  Mana recursion strikes have a 10 percent chance to strike the target repeatedly.  Mana recursion strikes generate little to no anger." },
