    [13718] = { level=254, name="Eldritch Rune", scroll_id=0, expac=3, mana=0, cast_ms=1, icon=2511, effectid1=10, desc="Self AC Buff", lore="This ability provides Enchanters with an additional line of defense in the form of an added self-only rune.  Each rank of this ability provides a stronger rune than the previous." },
