    [13723] = { level=254, name="Mind Over Matter", scroll_id=0, expac=3, mana=0, cast_ms=1, icon=2511, effectid1=329, desc="Self AC Buff", lore="While active, a portion of the damage you sustain is taken out of your mana rather than your hit points.  Any damage that cannot be absorbed by your mana comes off your hit points instead.  The first rank of this ability will absorb to 10 hits from spell or melee attacks before fading, the second rank will absorb 20, and the third will absorb 30, the fourth rank will absorb 40 hits, the fifth by 50, the sixth rank 60 hits. Additional ranks beyond rank 6 further increase the amount of damage that is mitigated by converting your mana." },
    [13724] = { level=254, name="Mind Over Matter", scroll_id=0, expac=3, mana=0, cast_ms=1, icon=2511, effectid1=329, desc="Self AC Buff", lore="While active, a portion of the damage you sustain is taken out of your mana rather than your hit points.  Any damage that cannot be absorbed by your mana comes off your hit points instead.  The first rank of this ability will absorb to 10 hits from spell or melee attacks before fading, the second rank will absorb 20, and the third will absorb 30, the fourth rank will absorb 40 hits, the fifth by 50, the sixth rank 60 hits. Additional ranks beyond rank 6 further increase the amount of damage that is mitigated by converting your mana." },
    [13725] = { level=254, name="Mind Over Matter", scroll_id=0, expac=3, mana=0, cast_ms=1, icon=2511, effectid1=329, desc="Self AC Buff", lore="While active, a portion of the damage you sustain is taken out of your mana rather than your hit points.  Any damage that cannot be absorbed by your mana comes off your hit points instead.  The first rank of this ability will absorb to 10 hits from spell or melee attacks before fading, the second rank will absorb 20, and the third will absorb 30, the fourth rank will absorb 40 hits, the fifth by 50, the sixth rank 60 hits. Additional ranks beyond rank 6 further increase the amount of damage that is mitigated by converting your mana." },
    [13732] = { level=254, name="Nightmare Stasis ", scroll_id=0, expac=3, mana=0, cast_ms=1500, icon=2504, effectid1=31, desc="Stun", lore="Use of this ability causes your opponent to immediately fall into a deep sleep and suffer terrible nightmares.  When they wake, their movements will be slowed while they recover from the effects.  The base ability affects NPCs up to level 74 and additional ranks increase the max level of NPC that can be affected 76 and 78 respectively for ranks 2 and 3. Ranks 4, 5 and 6 increase the cap to levels 79, 81 and 83, respectively and ranks 7, 8, and 9 raise the cap to level 84, 86 and 88." },
    [13733] = { level=254, name="Nightmare Stasis ", scroll_id=0, expac=3, mana=0, cast_ms=1500, icon=2504, effectid1=31, desc="Stun", lore="Use of this ability causes your opponent to immediately fall into a deep sleep and suffer terrible nightmares.  When they wake, their movements will be slowed while they recover from the effects.  The base ability affects NPCs up to level 74 and additional ranks increase the max level of NPC that can be affected 76 and 78 respectively for ranks 2 and 3. Ranks 4, 5 and 6 increase the cap to levels 79, 81 and 83, respectively and ranks 7, 8, and 9 raise the cap to level 84, 86 and 88." },
